import test from 'node:test';import assert from 'node:assert/strict';import {mkdtemp,readFile,rm} from 'node:fs/promises';import os from 'node:os';import path from 'node:path';import {createStore} from '../server/store.js';import {validatePack,installPack,exportChat,importChat,evaluationCase} from '../server/bundles.js';
test('packs never connect and portable exports round-trip without credentials or tool execution',async()=>{const home=await mkdtemp(path.join(os.tmpdir(),'apex-bundle-'));try{const {store}=await createStore(home),p=await store.createProject({name:'fixture',path:path.join(home,'project')}),s=await store.createSession({projectId:p.id}),key='sk-'+('a'.repeat(40));await store.appendMessage(s.id,{role:'user',content:'Make code '+key});await store.appendMessage(s.id,{role:'assistant',content:'Done',tool_calls:[{bad:'never export'}],providerState:{secret:key}});const file=path.join(home,'chat.json');await exportChat(store,s.id,file);const raw=await readFile(file,'utf8');assert.ok(!raw.includes(key));assert.ok(!raw.includes('providerState'));const imported=await importChat(store,p.id,file);assert.equal((await store.getSession(imported.id)).messages.length,2);assert.throws(()=>validatePack({version:1,name:'bad',servers:[{command:'x',env:{KEY:key}}]}),/Unsafe/);const pack=await installPack(store,{version:1,name:'local',servers:[{command:process.execPath,args:['--version'],envNames:[]}]});assert.equal(pack.connected,false);const receipt=await evaluationCase(store,{sessionId:s.id,expected:'passes a real test',file:path.join(home,'evaluation.json')});assert.equal((await store.record('evaluations',receipt.id)).trainingAdmitted,false);}finally{await rm(home,{recursive:true,force:true});}});
